from typing import List
import heapq

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        heap = []
        ans = []
        for i, value in enumerate(nums):
            heapq.heappush(heap, (-value, i))
            # Remove heap top entries that are outside the current window.
            while heap[0][1] <= i - k:
                heapq.heappop(heap)
            if i >= k - 1:
                ans.append(-heap[0][0])
        return ans

